from collections import defaultdict
class Solution:
    def minCost(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(n):
            cnt = defaultdict(int)
            singles = 0
            best = float('inf')
            for j in range(i, -1, -1):
                x = nums[j]
                cnt[x] += 1
                if cnt[x] == 1:
                    singles += 1
                elif cnt[x] == 2:
                    singles -= 1
                cand = dp[j] + k + (i - j + 1 - singles)
                if cand < best:
                    best = cand
            dp[i + 1] = best
        return dp[n]

