class Solution {
public:
    int minCost(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> dp(n + 1, LLONG_MAX / 2);
        dp[0] = 0;
        vector<int> cnt(n, 0);
        for (int i = 0; i < n; i++) {
            fill(cnt.begin(), cnt.end(), 0);
            int singles = 0;
            long long best = LLONG_MAX / 2;
            for (int j = i; j >= 0; j--) {
                int x = nums[j];
                if (++cnt[x] == 1) singles++;
                else if (cnt[x] == 2) singles--;
                best = min(best, dp[j] + k + (long long)(i - j + 1 - singles));
            }
            dp[i + 1] = best;
        }
        return (int) dp[n];
    }
};

