class Solution {
    public int minCost(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        int[] cnt = new int[n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(cnt, 0);
            int singles = 0;
            long best = Long.MAX_VALUE / 2;
            for (int j = i; j >= 0; j--) {
                int x = nums[j];
                if (++cnt[x] == 1) singles++;
                else if (cnt[x] == 2) singles--;
                best = Math.min(best, dp[j] + k + (i - j + 1 - singles));
            }
            dp[i + 1] = best;
        }
        return (int) dp[n];
    }
}

