var minCost = function(nums, k) {
    const n = nums.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        const cnt = new Map();
        let singles = 0, best = Infinity;
        for (let j = i; j >= 0; j--) {
            const x = nums[j];
            const c = (cnt.get(x) || 0) + 1;
            cnt.set(x, c);
            if (c === 1) singles++;
            else if (c === 2) singles--;
            best = Math.min(best, dp[j] + k + (i - j + 1 - singles));
        }
        dp[i + 1] = best;
    }
    return dp[n];
};
